import { useEffect, useState } from "react";
import { io } from "socket.io-client";
import "./PatientDashboard.css";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [form, setForm] = useState({
    patientName: "",
    department: "",
    date: ""
  });

  const [myOP, setMyOP] = useState(null);
  const [queues, setQueues] = useState([]);

  const fetchData = async () => {

    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();

    setQueues(data);

    // find current patient OP
    const mine = data.find(q => q.patientName === form.patientName);

    if (mine) {
      setMyOP(mine);
    } else {
      setMyOP(null); // 👈 if deleted → back to form
    }
  };

  useEffect(() => {
    fetchData();

    socket.on("queueUpdated", fetchData);

    return () => socket.off("queueUpdated");
  }, [form.patientName]);

  const bookOP = async () => {

    await fetch("http://localhost:5000/api/queue/book", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form)
    });

  };

  const joinQueue = async (id) => {
    await fetch(`http://localhost:5000/api/queue/join/${id}`, {
      method: "PUT"
    });
  };

  return (

    <div className="patient-page">

      {/* BOOK FORM */}
      {!myOP && (

        <div className="book-card">

          <h1>HealSync</h1>

          <input
            placeholder="Patient Name"
            onChange={(e) =>
              setForm({ ...form, patientName: e.target.value })
            }
          />

          <input
            placeholder="Department"
            onChange={(e) =>
              setForm({ ...form, department: e.target.value })
            }
          />

          <input
            type="date"
            onChange={(e) =>
              setForm({ ...form, date: e.target.value })
            }
          />

          <button onClick={bookOP}>
            Book OP
          </button>

        </div>

      )}

      {/* OP STATUS */}
      {myOP && (

        <div className="op-card">

          <h2>Your OP Details</h2>

          <p>Name: {myOP.patientName}</p>
          <p>Department: {myOP.department}</p>
          <p>Status: {myOP.status}</p>

          {myOP.status === "Confirmed" && (
            <button onClick={() => joinQueue(myOP._id)}>
              Join Queue
            </button>
          )}

          {myOP.status === "InQueue" && (
            <h3>Waiting in Queue...</h3>
          )}

        </div>

      )}

      {/* LIVE QUEUE LIST */}
      <div className="queue-list">

        <h3>Live Queue</h3>

        {queues.map(q => (
          <div key={q._id} className="queue-item">
            {q.patientName} - {q.status}
          </div>
        ))}

      </div>

    </div>

  );

}

export default PatientDashboard;
